'use strict';
(function(root){
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function grid(snapshot){return '<div class="buff-grid">'+(snapshot||[]).map(row=>'<section class="buff-member"><strong>左から'+(row.actor+1)+'人目</strong><div class="buff-chips">'+(row.buffs.length?row.buffs.map(b=>'<span class="buff-chip '+(b.remaining===1?'buff-expiring':'')+'" title="'+esc((b.clock||'持続未判定')+(b.extendable?'・延長可':'・延長不可／回数制'))+'">'+esc(b.name)+' '+esc(b.value+b.unit)+(b.remaining==null?'':' <b>残'+b.remaining+'回</b>')+'</span>').join(''):'<span class="muted">追加強化なし</span>')+'</div></section>').join('')+'</div>';}
function casts(damage){if(!damage?.casts?.length)return '';return '<div class="cast-breakdown"><h4>詠唱・追撃ごとの内訳</h4>'+damage.casts.map((d,i)=>{const f=d.factors||{};return '<p>'+(i+1)+'表示目 '+esc({cast:'通常詠唱',continuous:'連続呪文',echo:'やまびこ'}[d.kind]||d.kind)+'：<strong>'+d.min.toLocaleString()+'〜'+d.max.toLocaleString()+'</strong>／マナLv'+d.manaBefore+'→'+d.manaAfter+'／MP '+d.mpCost.max+'・回復'+d.mpRecovery+'</p><p class="muted">基礎威力 '+d.base+'／攻撃魔力 '+d.effectiveMagic+'／暴走 ×'+(f.criticalMin??1).toFixed(3)+'／マナ ×'+(f.mana??1).toFixed(3)+'／追撃威力 ×'+(f.echo??(d.kind==='echo'?.5:1)).toFixed(3)+'／ため ×'+(f.charge??1).toFixed(3)+'</p>';}).join('')+'<p class="muted">やまびこの威力は基本50%で計算。こころ道のやまびこ威力追加は未対応です。マナは各表示の発動前Lvを使う比較モデルです。</p></div>';}
function action(step){if(!step.buffsBefore&&!step.buffsAfter)return '';const own=step.buffsBefore?.find(row=>row.actor===step.actor);return (step.damage&&own?'<div class="buff-current"><strong>攻撃時の強化</strong>'+grid([own])+'</div>':'')+casts(step.damage)+'<details class="buff-inspector"><summary>4人のバフ・残り持続を確認</summary><p class="muted">「残り」は本人の行動終了までの回数。アンコール等でも進みます。祈りは通常行動開始の回数、ためは次の対応攻撃まで。魔響の詠唱・真魔解放と、それぞれの直後のAI攻撃は合わせて1行動として消費します。ゲームのターン表示とは区別しています。</p><h4>行動直前</h4>'+grid(step.buffsBefore)+(step.setupAction?'<h4>補助設定後（直後のAI攻撃まで持続を保留）</h4>':'<h4>行動終了後</h4>')+grid(step.buffsAfter)+(step.aiControlled?'<p class="notice">AIが指定した攻撃を選んだ場合の条件付き結果です。選択率は未確認。</p>':'')+(step.damage?.referenceOnly?'<p class="notice">超暴走・マナは公開検証の代表倍率による参考値。実測の最低/最大ダメージではありません。</p>':'')+'</details>';}
function probability(info){if(!info)return '';const text=info.probability==null?'未算定（発動・AI選択率が未確認、または独立仮定が未指定）':info.events.length?(info.probability*100).toLocaleString('ja-JP',{maximumFractionDigits:4})+(info.events.length===1?'%（入力した成立率）':'%（入力値・独立仮定）'):'確率発動の追加条件なし';return '<details class="proc-summary"><summary>再現に必要な確率条件：'+esc(text)+'</summary><p>'+esc(info.scope)+'</p>'+info.events.map(e=>'<p>'+esc(e.label)+'：'+(e.rate==null?'未確認・未入力':(e.rate*100).toFixed(2)+'%')+'</p>').join('')+(info.assumptions||[]).map(x=>'<p>'+esc(x)+'</p>').join('')+'</details>';}
root.BuffTimeline35={grid,action,probability};
})(typeof window==='undefined'?globalThis:window);

